Translate("ptBR", "eastern-plaguelands", {
	title = "Terras Pestilentas Orientais",
	aliases = { "Pestilentas Orientais" },
	sections = {
		{
			title = "Resumo",
			text = [=[As Terras Pestilentas Orientais são o coração morto do que um dia foi {link:lordaeron}Lordaeron{/link}. Aqui a praga da morte-vida caiu primeiro e com mais força, e aqui ela nunca se dissipou. As florestas são cinzentas e cobertas de podridão. Os rios correm lentos e imundos. As fazendas e aldeias que outrora alimentavam a grande cidade de {red:stratholme}Stratholme{/red} estão vazias, ou pior que vazias, pois seu povo ainda anda pelas estradas a serviço do {link:scourge}Flagelo{/link}. Nenhum rei governa estas terras. O Flagelo as domina, a {link:scarlet-crusade}Cruzada Escarlate{/link} as disputa a partir da fortaleza de {link:tyr-s-hand}Manopla de Tyr{/link}, e um pequeno grupo da {link:argent-dawn}Aurora Argêntea{/link} mantém uma única lâmpada acesa na {link:light-s-hope-chapel}Capela Esperança da Luz{/link}, no extremo leste.]=],
		},
		{
			title = "Origens",
			text = [=[Antes da praga, as marcas orientais de {link:lordaeron}Lordaeron{/link} eram uma região rica e tranquila. Stratholme era a segunda cidade do reino, e ao seu redor ficavam fazendas, moinhos e aldeias como a {link:darrowshire}Vila das Flechas{/link}, o {link:northdale}Vilarejo do Norte{/link} e o {link:corin-s-crossing}Cruzamento de Corin{/link}. {link:tyr-s-hand}Manopla de Tyr{/link} guardava a costa sudeste. No norte, além do {link:thondroril-river}Thondroril{/link} e das florestas, o reino de {link:quel-thalas}Quel'Thalas{/link} mantinha seus abrigos de fronteira, e os altos elfos que caçavam ali eram vizinhos e amigos. Nenhuma crônica registra quando a primeira dessas aldeias foi fundada. O que está escrito é como elas terminaram.]=],
		},
		{
			title = "Os Dias Atuais",
			text = [=[A terra é um campo de batalha sem frente. O {link:cult-of-the-damned}Culto dos Malditos{/link} ergue seus templos sombrios no {link:corin-s-crossing}Cruzamento de Corin{/link} e no {link:plaguewood}Bosque Pestilento{/link}, onde o {link:scourge}Flagelo{/link} constrói e costura novos servos. Morcegos da peste escurecem os céus, cães da peste caçam nas estradas, e as larvas carniceiras engordam com os mortos. A {link:scarlet-crusade}Cruzada Escarlate{/link} ocupa {link:tyr-s-hand}Manopla de Tyr{/link} e envia suas patrulhas ao norte, rumo a Stratholme, matando todos que não vestem suas cores. Contra tudo isso ergue-se a {link:light-s-hope-chapel}Capela Esperança da Luz{/link}, onde {link:lord-maxwell-tyrosus}Lorde Maxwell Tyrosus{/link} e a {link:argent-dawn}Aurora Argêntea{/link} aceitam qualquer aliado, vivo ou morto, que lute contra o Flagelo. Os {link:forsaken}Renegados{/link} têm aqui o seu próprio campeão. {link:nathanos-blightcaller}Nathanos Blightcaller{/link} guarda o {link:the-marris-stead}Sítio dos Marris{/link}, no sudoeste, e caça tanto o Flagelo quanto os vivos. E numa cabana junto ao rio do oeste vive um velho que um dia foi paladino do Punho de Prata, {link:tirion-fordring}Tirion Fordring{/link}.]=],
		},
		{
			title = "Habitantes",
			text = [=[• {b}O {link:scourge}Flagelo{/link}.{/b} Carniçais, abominações, gárgulas e os mortos erguidos das aldeias do leste enchem a terra. Servem ao Lich Rei por meio dos necromantes do {link:cult-of-the-damned}Culto dos Malditos{/link}.
• {b}A {link:scarlet-crusade}Cruzada Escarlate{/link}.{/b} Seus cavaleiros e clérigos ocupam {link:tyr-s-hand}Manopla de Tyr{/link} e a Basílica Escarlate. Guerreiam contra o Flagelo e contra todos os demais.
• {b}A {link:argent-dawn}Aurora Argêntea{/link}.{/b} Da {link:light-s-hope-chapel}Capela Esperança da Luz{/link}, seus cavaleiros, estudiosos e intendentes travam uma guerra paciente contra os mortos-vivos e recompensam quem lhes traz as provas da luta.
• {b}Os {link:forsaken}Renegados{/link}.{/b} {link:nathanos-blightcaller}Nathanos Blightcaller{/link}, o campeão da Rainha Banshee, trava sua própria guerra a partir do {link:the-marris-stead}Sítio dos Marris{/link}.
• {b}Os altos elfos de {link:quel-lithien-lodge}Quel'Lithien{/link}.{/b} Num abrigo na fronteira norte, patrulheiros de {link:quel-thalas}Quel'Thalas{/link} ainda mantêm sua vigília.
• {b}Os trolls Mossflayer.{/b} Da cidade arruinada de {link:zul-mashar}Zul'Mashar{/link}, uma tribo de {link:trolls}trolls da floresta{/link} luta para sobreviver. A praga já alcançou alguns deles.
• {b}Os mortos que não descansam.{/b} Fantasmas andam pela {link:darrowshire}Vila das Flechas{/link} e pela {link:terrordale}Várzea do Medo{/link}, e alguns deles ainda esperam que os vivos voltem para casa.]=],
		},
		{
			title = "História",
			text = [=[• {b}A Praga.{/b} O {link:cult-of-the-damned}Culto dos Malditos{/link} espalhou a praga da morte-vida pelos grãos de {link:lordaeron}Lordaeron{/link}. As aldeias do leste os comeram e morreram, e então se ergueram.
• {b}O Expurgo de Stratholme.{/b} O Príncipe {link:arthas-menethil}Arthas Menethil{/link} passou Stratholme a fio de espada para não deixar que seu povo contaminado se erguesse, e a cidade ardeu. O {link:culling-of-stratholme}Expurgo de Stratholme{/link} é lembrado nestas terras como o dia em que o leste foi perdido.
• {b}A Queda de Lordaeron.{/b} Depois que o príncipe voltou do norte como cavaleiro da morte, o reino caiu. Na {link:fall-of-lordaeron}Queda de Lordaeron{/link}, as aldeias do leste foram tomadas uma a uma. Na {link:darrowshire}Vila das Flechas{/link}, os defensores resistiram de um modo que os Anais da Vila das Flechas ainda recordam.
• {b}As Guerras dos Mortos.{/b} O {link:scourge}Flagelo{/link} fez do leste sua fortaleza. A {link:scarlet-crusade}Cruzada Escarlate{/link} surgiu dos sobreviventes e tomou {link:tyr-s-hand}Manopla de Tyr{/link}. A {link:argent-dawn}Aurora Argêntea{/link} separou-se da Cruzada e encontrou seu lar na {link:light-s-hope-chapel}Capela Esperança da Luz{/link}. Os {link:forsaken}Renegados{/link} vieram para o leste quando {link:sylvanas-windrunner}a Rainha Banshee{/link} saiu à procura de um de seus antigos patrulheiros.]=],
		},
		{
			title = "Saberes das Terras Pestilentas",
			text = [=[• O povo da {link:light-s-hope-chapel}Esperança da Luz{/link} diz que a pequena {link:pamela-redpath}Pamela Redpath{/link} ainda espera em sua casa ao sul da {link:darrowshire}Vila das Flechas{/link}, e que em noites silenciosas pode-se ouvi-la pedindo sua boneca aos viajantes.
• Os que passam pela {link:terrordale}Várzea do Medo{/link} falam de um mercador de lá cujos preços, segundo ele próprio, são insanos. Não têm certeza de que a palavra seja apenas uma bravata.
• A {link:argent-dawn}Aurora Argêntea{/link} paga em bravura pelas pedras do {link:scourge}Flagelo{/link} que os mortos carregam. Seus intendentes mantêm uma contagem cuidadosa.
• Diz-se que o campeão Renegado no {link:the-marris-stead}Sítio dos Marris{/link} chama de imbecil todo servo vivo que chega até ele, e que essa é sua palavra mais gentil.]=],
		},
	},
})

Translate("ptBR", "light-s-hope-chapel", {
	title = "Capela Esperança da Luz",
	aliases = { "Esperança da Luz" },
	sections = {
		{
			title = "Resumo",
			text = [=[A Capela Esperança da Luz ergue-se numa elevação verde no extremo leste das Terras Pestilentas, o único pedaço de chão limpo por muitas léguas. É o lar da {link:argent-dawn}Aurora Argêntea{/link}. Ao redor da velha capela, a {link:aurora-skycaller}Aurora{/link} ergueu tendas, forjas e estábulos, e suas sentinelas vigiam as estradas dia e noite. {link:lord-maxwell-tyrosus}Lorde Maxwell Tyrosus{/link} reúne seu conselho dentro da capela. {link:duke-nicholas-zverenhoff}O Duque{/link} Nicholas Zverenhoff, {link:carlin-redpath}Carlin Redpath{/link}, o cavaleiro morto-vivo {link:leonid-barthalomew}Leonid Barthalomew{/link} e a alquimista {link:betina-bigglezink}Betina Bigglezink{/link} trabalham sob suas paredes. Viajantes de todas as raças vêm para cá, pois a Aurora não pergunta quem seus aliados foram antes. Abaixo da elevação há uma vala onde a Aurora deposita seus mortos, e nem mesmo estes estão a salvo de ladrões.]=],
		},
	},
})

Translate("ptBR", "tyr-s-hand", {
	title = "Manopla de Tyr",
	aliases = { "Basílica Escarlate" },
	sections = {
		{
			title = "Resumo",
			text = [=[Manopla de Tyr é uma cidade murada na costa sudeste das Terras Pestilentas e o maior baluarte da {link:scarlet-crusade}Cruzada Escarlate{/link} no leste. Sua guarnição responde ao {link:high-general-abbendis}Grão-general Abbendis{/link}, e a Basílica Escarlate ergue-se em seu coração. Todos os dias um mensageiro cavalga entre Manopla de Tyr e o comando da Cruzada no norte, e todos os dias a cidade envia seus soldados contra o {link:scourge}Flagelo{/link}. Os cruzados não confiam em nenhum estranho. Quem chega aos portões sem as cores da Cruzada é abatido. Os {link:forsaken}Renegados{/link}, que foram os que mais sofreram nas mãos da Cruzada, vigiam a cidade de perto.]=],
		},
	},
})

Translate("ptBR", "corin-s-crossing", {
	title = "Cruzamento de Corin",
	aliases = { "Corin" },
	sections = {
		{
			title = "Resumo",
			text = [=[O Cruzamento de Corin era uma aldeia no encontro das velhas estradas, no meio das marcas orientais. Agora é um ninho do {link:cult-of-the-damned}Culto dos Malditos{/link}. Suas casas estão cheias de cultistas e mortos erguidos, e o {link:scourge}Flagelo{/link} que se reúne ali é tão denso que {link:nathanos-blightcaller}Nathanos Blightcaller{/link} envia seus servos até lá em busca de carniça fresca. A oeste da aldeia abre-se na terra uma garganta profunda. Os Anais da {link:darrowshire}Vila das Flechas{/link} dizem que a espada de Marduk, o Negro, jaz quebrada no fundo dela, e que o corpo de {link:horgus-the-ravager}Horgus, o Devastador{/link}, foi lançado num lago a noroeste.]=],
		},
	},
})

Translate("ptBR", "darrowshire", {
	title = "Vila das Flechas",
	sections = {
		{
			title = "Resumo",
			text = [=[A Vila das Flechas era uma aldeia nas colinas do sul das marcas orientais. Quando o {link:scourge}Flagelo{/link} chegou, seu povo não fugiu. Sob o {link:joseph-redpath}Capitão Joseph Redpath{/link}, eles ficaram e lutaram, e ali morreram. Os Anais da Vila das Flechas registram que o próprio capitão foi corrompido na batalha e se voltou contra os seus. Agora a aldeia é uma ruína, e seus mortos não descansam. Fantasmas andam por sua praça. Ao sul das ruínas fica a casa dos Redpath, onde uma menininha ainda espera que o pai volte da luta.]=],
		},
	},
})

Translate("ptBR", "the-marris-stead", {
	title = "Sítio dos Marris",
	aliases = { "Sítio dos Marris" },
	sections = {
		{
			title = "Resumo",
			text = [=[O Sítio dos Marris é uma fazenda no sudoeste das Terras Pestilentas, perto da fronteira com as terras do oeste. Foi o lar de {link:nathanos-blightcaller}Nathanos Marris{/link}, um senhor patrulheiro de {link:lordaeron}Lordaeron{/link}. Quando o {link:scourge}Flagelo{/link} varreu a região, Nathanos resistiu nesta fazenda, e aqui tombou. Ele voltou a ela como servo da Rainha Banshee. Agora vive ali com seus cães, e os vivos que chegam à fazenda são ou {link:forsaken}Renegados{/link} em missões da Dama Sombria ou soldados da {link:alliance}Aliança{/link} enviados para acabar com ele. Crânios jazem espalhados pelos campos.]=],
		},
	},
})

Translate("ptBR", "terrordale", {
	title = "Várzea do Medo",
	aliases = { "Túnel Terrorteia" },
	sections = {
		{
			title = "Resumo",
			text = [=[A Várzea do Medo fica no noroeste das Terras Pestilentas, onde a terra desce rumo à fronteira oeste. Já foi uma cidade, com uma estalagem e um mercado. Agora suas ruas são assombradas, e os demônios da cripta do {link:scourge}Flagelo{/link} rastejam pelo longo Túnel Terrorteia que a liga às terras do oeste. Dois homens estranhos vivem entre as ruínas. {link:egan}Egan{/link} caça fantasmas com um aparelho de sua própria invenção. {link:augustus-the-touched}Augustus{/link}, a quem os viajantes chamam de o Tocado, espera para reabrir sua loja.]=],
		},
	},
})

Translate("ptBR", "plaguewood", {
	title = "Bosque Pestilento",
	aliases = { "Fortaleza do Flagelo" },
	sections = {
		{
			title = "Resumo",
			text = [=[O Bosque Pestilento é uma floresta arruinada pela praga no noroeste, espalhada ao redor das muralhas de {red:stratholme}Stratholme{/red}. É um lugar de trabalho do {link:scourge}Flagelo{/link}. Zigurates e abatedouros erguem-se entre as árvores mortas, e o Flagelo os guarda de perto, pois os mortos tiram poder dessas construções e costuram novos horrores dentro delas. Os carniçais e esfoladores que vagam pelo bosque já foram o povo das aldeias do leste. A {link:argent-dawn}Aurora Argêntea{/link} contratou um especialista em demolição para derrubar as construções.]=],
		},
	},
})

Translate("ptBR", "zul-mashar", {
	title = "Zul'Mashar",
	aliases = { "Mazra'Alor" },
	sections = {
		{
			title = "Resumo",
			text = [=[Zul'Mashar é uma cidade troll arruinada no extremo nordeste das Terras Pestilentas, perto das fronteiras de {link:quel-thalas}Quel'Thalas{/link}. Os trolls Mossflayer a ocupam sob o Senhor da Guerra Thresh'jin e o mandingueiro Zul'Brin Warpbranch. A praga também os encontrou. Alguns de seus batedores comeram carne contaminada no caminho de volta, e a voz de um lich agora os impele a levar a doença ao seu próprio povo. A sudoeste da cidade ficam as ruínas mais antigas de Mazra'Alor.]=],
		},
	},
})

Translate("ptBR", "the-noxious-glade", {
	title = "Clareira Nociva",
	aliases = { "Clareira Nociva" },
	sections = {
		{
			title = "Resumo",
			text = [=[A Clareira Nociva é um vale envenenado no nordeste das Terras Pestilentas, ao norte da {link:light-s-hope-chapel}Esperança da Luz{/link}. Seu ar é denso e verde, e gosmas de decomposição viva rastejam por suas depressões. O {link:scourge}Flagelo{/link} mantém seus campeões aqui, e o {link:cult-of-the-damned}Culto dos Malditos{/link} conduz ritos sombrios entre as árvores. Alguns dos campeões que andam pela clareira lutaram na batalha da {link:darrowshire}Vila das Flechas{/link}, e seus crânios ainda ressoam com a lembrança dela.]=],
		},
	},
})

Translate("ptBR", "thondroril-river", {
	title = "Rio Thondroril",
	aliases = { "Thondroril" },
	sections = {
		{
			title = "Resumo",
			text = [=[O Thondroril é o rio que separa as Terras Pestilentas do leste das do oeste. Suas águas são escuras e lentas, e poucos viajantes se demoram em suas margens. Ainda assim, na margem leste, escondida entre as árvores, há uma pequena cabana com uma linha de pesca e uma fogueira. Um velho vive ali sozinho com seu cavalo, Mirador. Seu nome é {link:tirion-fordring}Tirion Fordring{/link}. Ele já foi lorde e paladino do Punho de Prata, e perdeu os dois títulos por causa de um {link:orcs}orc{/link}. Ele só pede a seus hóspedes que ajudem com os cães e os morcegos e, em troca, oferece uma refeição quente e a história de sua vida.]=],
		},
	},
})

Translate("ptBR", "crown-guard-tower", {
	title = "Torre da Coroa",
	aliases = { "Torre da Coroa" },
	sections = {
		{
			title = "Resumo",
			text = [=[A Torre da Coroa é uma velha torre de vigia de {link:lordaeron}Lordaeron{/link} na estrada do sul, entre a {link:darrowshire}Vila das Flechas{/link} e o {link:the-marris-stead}Sítio dos Marris{/link}. Foi erguida para guardar as estradas do rei no leste. O rei está morto e as estradas pertencem ao {link:scourge}Flagelo{/link}, mas a torre ainda está de pé, um dedo solitário de pedra acima da praga. Soldados dos vivos às vezes se abrigam nela. Nenhum deles fica por muito tempo.]=],
		},
	},
})

Translate("ptBR", "quel-lithien-lodge", {
	title = "Abrigo Quel'Lithien",
	aliases = { "Quel'Lithien" },
	sections = {
		{
			title = "Resumo",
			text = [=[O Abrigo Quel'Lithien é um pavilhão de caça dos altos elfos na fronteira norte das Terras Pestilentas, perto da estrada para {link:quel-thalas}Quel'Thalas{/link}. Patrulheiros, mateiros e desbravadores montam guarda aqui sob o {link:ranger-lord-hawkspear}Senhor Patrulheiro Hawkspear{/link}. O abrigo também guarda registros dos velhos tempos, quando os altos elfos treinavam os patrulheiros de {link:lordaeron}Lordaeron{/link}. Entre eles estão os Arquivos de Quel'Thalas, que contam a vida mortal de {link:nathanos-blightcaller}Nathanos Marris{/link}. O Blightcaller os quer de volta, e não se importa com quantos elfos terão de sofrer por isso.]=],
		},
	},
})

Translate("ptBR", "the-undercroft", {
	title = "Chácara Secreta",
	aliases = { "Chácara Secreta" },
	sections = {
		{
			title = "Resumo",
			text = [=[A Chácara Secreta é uma velha cripta no sudoeste das Terras Pestilentas, ao sul do {link:the-marris-stead}Sítio dos Marris{/link}. Era um lugar de repouso para os mortos das aldeias do leste. Entre seus túmulos há um falso. Quando {link:tirion-fordring}Tirion Fordring{/link} foi banido, disseram a seu filho que o pai havia morrido, e o menino foi trazido aqui para chorá-lo. Agora a cripta é o esconderijo de ladrões trolls mortos liderados por {link:zaeldarr-the-outcast}Zaeldarr, o Pária{/link}, que saem à noite para roubar cadáveres da vala da {link:light-s-hope-chapel}Esperança da Luz{/link}. Atrás da cripta, ao lado de uma velha carroça, um Mossflayer enterrou um baú antes que a praga lhe tomasse a mente.]=],
		},
	},
})

Translate("ptBR", "northdale", {
	title = "Vilarejo do Norte",
	sections = {
		{
			title = "Resumo",
			text = [=[O Vilarejo do Norte era uma aldeia no nordeste das Terras Pestilentas, além da {link:light-s-hope-chapel}Esperança da Luz{/link}. Quando o Punho de Prata foi desfeito, o jovem paladino {link:taelan-fordring}Taelan Fordring{/link} resistiu pela última vez no Vilarejo do Norte, e ali lançou ao chão o estandarte da ordem. O estandarte ainda jaz entre as ruínas. A oeste da aldeia, nas terras ermas do norte, vaga o grande verme {link:borelgore}Borelgore{/link}, que já engoliu bandos inteiros de soldados.]=],
		},
	},
})

Translate("ptBR", "the-fungal-vale", {
	title = "Vale Fungi",
	aliases = { "Vale Fungi" },
	sections = {
		{
			title = "Resumo",
			text = [=[O Vale Fungi é um vale afundado no oeste das Terras Pestilentas, onde cogumelos gigantes crescem na podridão da praga. O {link:scourge}Flagelo{/link} mantém seus campeões aqui, como faz na {link:the-noxious-glade}Clareira Nociva{/link}, e o {link:cult-of-the-damned}Culto dos Malditos{/link} construiu um acampamento entre os fungos. É também o refúgio do morcego demoníaco albino {link:duskwing}Duskwing{/link}, a única criatura que o {link:nathanos-blightcaller}Blightcaller{/link} odeia abertamente.]=],
		},
	},
})

Translate("ptBR", "northpass-tower", {
	title = "Torre do Passo Norte",
	aliases = { "Passo Norte" },
	sections = {
		{
			title = "Resumo",
			text = [=[A Torre do Passo Norte guarda a estrada que sai das Terras Pestilentas para o norte, rumo aos desfiladeiros de {link:quel-thalas}Quel'Thalas{/link}. Foi construída para vigiar a fronteira entre homens e elfos quando essa fronteira era amigável. Perto da torre vive a alta elfa {link:aurora-skycaller}Aurora Skycaller{/link}, guardiã de antigos saberes élficos que lamenta os erros de seus ancestrais. Poucos vêm até ela, e menos ainda vêm com uma pergunta que ela esteja disposta a responder.]=],
		},
	},
})

Translate("ptBR", "nathanos-blightcaller", {
	title = "Nathanos Blightcaller",
	subtitle = "Campeão da Rainha Banshee",
	found = "O Sítio dos Marris, no sudoeste das Terras Pestilentas",
	hint = [=[Procure o patrulheiro Renegado que mantém uma fazenda de crânios e cães no sudoeste.]=],
	allegiance = "Renegados · Sylvanas Windrunner",
	aliases = { "Nathanos", "Nathanos Marris", "Blightcaller" },
	sections = {
		{
			title = "Resumo",
			text = [=[Nathanos Blightcaller é o campeão dos {link:forsaken}Renegados{/link} nas {link:eastern-plaguelands}Terras Pestilentas Orientais{/link}. Em vida, foi Nathanos Marris, um senhor patrulheiro de {link:lordaeron}Lordaeron{/link} e o único humano a quem se permitiu treinar entre os patrulheiros de {link:quel-thalas}Quel'Thalas{/link}. Ele tombou diante do {link:scourge}Flagelo{/link} em sua própria fazenda e se ergueu como seu escravo. {link:sylvanas-windrunner}Sylvanas Windrunner{/link} o libertou. Agora ele guarda o {link:the-marris-stead}Sítio dos Marris{/link} com seus cães da praga e caça o Flagelo e os vivos com o mesmo ódio frio. É cruel com os que o servem e não confia em ninguém além da Dama Sombria.]=],
		},
		{
			title = "Importância",
			text = [=[Nathanos é duas coisas ao mesmo tempo, e os dois lados da guerra sabem disso. Para a {link:alliance}Aliança{/link}, ele foi um herói. Sua habilidade conquistou vitórias ao longo de uma década de guerra, e nenhum outro humano chegou à patente de senhor patrulheiro. Para os {link:forsaken}Renegados{/link}, ele é o primeiro e o mais temido dos campeões da Rainha Banshee. Seu destino é uma ferida para a Aliança. O regente de {link:stormwind-city}Ventobravo{/link} soube dele e enviou um exército para acabar com ele.]=],
		},
		{
			title = "Vida e Morte",
			text = [=[Nathanos nasceu humano em {link:lordaeron}Lordaeron{/link}. Os altos elfos o acolheram em sua ordem de patrulheiros, o que nunca haviam feito por ninguém de sua raça, e ele chegou à mais alta patente. Quando o {link:scourge}Flagelo{/link} varreu as marcas orientais, ele resistiu em sua fazenda em defesa do reino. Uma grande onda de mortos o sobrepujou. A última coisa que viu foi uma abominação pairando sobre ele, com as entranhas pendendo do peito. Ele despertou como parte do Flagelo, com a mente presa à do Lich Rei. Ficou indefeso por muito tempo. Então {link:sylvanas-windrunner}a Rainha Banshee{/link} veio buscá-lo, como ele de algum modo sabia que ela viria, e quebrou suas correntes.]=],
		},
		{
			title = "Feitos",
			text = [=[• Ele caçou a abominação Ramstein pelas terras ermas durante meses após sua libertação, até que ela fugiu para Stratholme.
• Ele treina os {link:forsaken}Renegados{/link} que {link:sylvanas-windrunner}a Dama Sombria{/link} lhe envia, com desprezo e sem piedade.
• Ele matou os agentes do {link:si-7}SI:7{/link} que {link:stormwind-city}Ventobravo{/link} enviou para descobrir quem era o Blightcaller.
• Ele conspira contra a {link:scarlet-crusade}Cruzada Escarlate{/link} por ordens de {link:varimathras}Varimathras{/link}.]=],
		},
		{
			title = "Os Dias Atuais",
			text = [=[Nathanos guarda o {link:the-marris-stead}Sítio dos Marris{/link} sozinho com seus cães. Envia seus servos para alimentar os cães com podridão do {link:corin-s-crossing}Cruzamento de Corin{/link}, para livrar seu céu dos morcegos da peste e para caçar os monstros do norte. Os {link:forsaken}Renegados{/link} que sobrevivem ao seu treinamento ganham um lugar entre seus campeões. Os soldados da {link:alliance}Aliança{/link} que chegam ao sítio normalmente não saem dele.]=],
		},
	},
	chapters = {
		{
			title = "O Campeão da Rainha Banshee",
			hint = [=[Atenda ao chamado da Dama Sombria e apresente-se no Sítio dos Marris.]=],
			text = [=[A Rainha Banshee envia seus servos mais experientes para o leste, ao {link:the-marris-stead}Sítio dos Marris{/link}. Nathanos os recebe com escárnio. Supõe que vieram alimentar seus cães, pois não consegue imaginar outro motivo para virem incomodá-lo.]=],
		},
		{
			title = "Matar com Propósito",
			hint = "Faça por merecer seu lugar no Sítio dos Marris.",
			text = [=[As primeiras lições de Nathanos são tarefas. Seus servos moem a podridão do {link:scourge}Flagelo{/link} recém-abatido como ração para seus cães e caçam os morcegos da peste que o importunam sempre que ele deixa a fazenda. Ele chama isso de treinamento. Diz também que tem coisas melhores a fazer do que matar morcegos, e seus servos não têm.]=],
		},
		{
			title = "A Incumbência do Senhor Patrulheiro",
			hint = [=[Recupere dos elfos do norte um registro da vida mortal do Blightcaller.]=],
			text = [=[No {link:quel-lithien-lodge}Abrigo Quel'Lithien{/link}, os altos elfos guardavam um registro de sua vida como mortal. Nathanos o queria de volta, e queria que os elfos que o guardavam sofressem. Não disse por quê. Apenas advertiu que nenhum servo seu fosse tolo a ponto de lê-lo.]=],
		},
		{
			title = "Ramstein",
			hint = "Vingue a morte do Blightcaller.",
			text = [=[Foi a abominação Ramstein que pairou sobre Nathanos enquanto ele morria. Depois que {link:sylvanas-windrunner}Sylvanas{/link} o libertou, ele a caçou durante meses, até que ela fugiu para Stratholme. Quando sua cabeça lhe foi trazida, ele se perguntou em voz alta se ela havia implorado, e se sequer podia saber o que era misericórdia. Jurou pendurar a cabeça em sua parede.]=],
		},
		{
			title = "O Oráculo Escarlate",
			hint = "Execute o ardil do Blightcaller contra a Cruzada Escarlate.",
			text = [=[{link:varimathras}Varimathras{/link} mandou dizer que o Grão-cruzado da {link:scarlet-crusade}Cruzada Escarlate{/link} precisava ser golpeado. Nathanos encontrou a fraqueza no mensageiro diário da Cruzada. Reescreveu as ordens do Grão-cruzado e enviou a {link:tyr-s-hand}Manopla de Tyr{/link} um servo disfarçado de cruzado. As ordens pediam que o Oráculo Escarlate, {link:demetria}Demetria{/link}, principal conselheira do Grão-cruzado, fosse enviada ao norte, a Stratholme. A Cruzada obedeceu. Nathanos esperava na estrada.]=],
		},
		{
			title = "O Blightcaller Desmascarado",
			hint = "Descubra quem é o Blightcaller, em nome de Ventobravo.",
			text = [=[Três agentes do {link:si-7}SI:7{/link} entraram nas {link:eastern-plaguelands}Terras Pestilentas Orientais{/link} para descobrir quem era o Blightcaller, e nenhum voltou. Suas insígnias foram encontradas perto do {link:the-marris-stead}Sítio dos Marris{/link}. Quando a verdade veio à tona, partiu o coração dos que haviam conhecido Nathanos Marris. O regente de {link:stormwind-city}Ventobravo{/link} não pôde acreditar que o senhor patrulheiro se tornara o campeão da Rainha Banshee, e convocou um exército para acabar com ele.]=],
		},
	},
	mentions = {
		{ text = "O Campeão da Rainha Banshee" },
		{ text = "Matar com Propósito" },
		{ text = "Os Pequenos Aborrecimentos da Morte-vida" },
		{ text = "A Incumbência do Senhor Patrulheiro" },
		{ text = "{link:duskwing}Duskwing{/link}, Ah, Como Eu Te Odeio..." },
		{ text = "{link:borelgore}O Corpulento{/link}" },
		{ text = "Ramstein" },
		{ text = "O Chamado ao Comando" },
		{ text = "O Mensageiro Carmesim" },
		{ text = "O Ardil de Nathanos" },
		{ text = "De Volta a Nathanos" },
		{ text = "{link:demetria}O Oráculo Escarlate{/link}, Demetria" },
		{ text = "As Pestes do Leste" },
		{ text = "O Blightcaller Vem Aí" },
		{ text = "A Ordem Precisa Ser Restaurada" },
	},
	bonds = {
		{ id = "sylvanas-windrunner", name = "Sylvanas Windrunner", note = "libertou-o do Lich Rei" },
		{ id = "varimathras", name = "Varimathras", note = "envia-lhe ordens da Cidade Baixa" },
		{ id = "bolvar-fordragon", name = "Bolvar Fordragon", note = "exige sua morte" },
		{ id = "ranger-lord-hawkspear", name = "Senhor Patrulheiro Hawkspear", note = "guarda o registro de sua vida mortal" },
		{ id = "duskwing", name = "Duskwing", note = "o morcego que ele odeia" },
		{ id = "borelgore", name = "Borelgore", note = "custou-lhe regimentos inteiros" },
		{ id = "demetria", name = "Demetria", note = "o Oráculo que ele caçou" },
	},
})

Translate("ptBR", "lord-maxwell-tyrosus", {
	title = "Lorde Maxwell Tyrosus",
	subtitle = "Líder da Aurora Argêntea",
	found = "Dentro da Capela Esperança da Luz",
	hint = [=[Procure o lorde que reúne seu conselho dentro da capela da Esperança da Luz.]=],
	allegiance = "Aurora Argêntea",
	aliases = { "Maxwell Tyrosus", "Tyrosus", "Lorde Maxwell" },
	sections = {
		{
			title = "Resumo",
			text = [=[Lorde Maxwell Tyrosus lidera a {link:argent-dawn}Aurora Argêntea{/link} de dentro da capela da {link:light-s-hope-chapel}Esperança da Luz{/link}. Ele já pertenceu à {link:scarlet-crusade}Cruzada Escarlate{/link}. Quando viu aonde o zelo dela levava, recusou-se a segui-la e ajudou a fundar uma ordem que combateria o {link:scourge}Flagelo{/link} sem odiar todos os demais. Ele raramente deixa a capela e, há anos, não concede audiência a estranhos. Os que são levados à sua presença fizeram por merecer.]=],
		},
		{
			title = "Importância",
			text = [=[Tyrosus é o coração do grande experimento da {link:aurora-skycaller}Aurora{/link}: uma ordem que não pergunta a ninguém a que raça ou estandarte serviu, apenas se vai enfrentar os mortos. Ao seu redor reúnem-se um cavaleiro morto-vivo, uma alquimista {link:gnomes}gnomo{/link}, um linguista nobre e um filho enlutado da {link:darrowshire}Vila das Flechas{/link}. Que trabalhem juntos, afinal, é obra dele.]=],
		},
		{
			title = "Feitos",
			text = [=[• Ele deixou a {link:scarlet-crusade}Cruzada Escarlate{/link} e ajudou a fundar a {link:argent-dawn}Aurora Argêntea{/link}.
• Ele lidera a {link:aurora-skycaller}Aurora{/link} em sua guerra contra o {link:scourge}Flagelo{/link} a partir da {link:light-s-hope-chapel}Capela Esperança da Luz{/link}.
• Ele guarda o {link:the-bulwark}Baluarte{/link} Argênteo, que permaneceu trancado por anos.]=],
		},
		{
			title = "Sem Registro",
			text = [=[As crônicas pouco dizem da vida de Tyrosus antes da Cruzada, ou das terras por trás de seu título. Este registro guarda apenas seu lugar na {link:aurora-skycaller}Aurora{/link}.]=],
		},
	},
	chapters = {
		{
			title = "Uma Audiência com Lorde Maxwell",
			hint = [=[Prove ser um campeão da Aurora e seja levado à presença de seu líder.]=],
			text = [=[{link:duke-nicholas-zverenhoff}O Duque{/link} Nicholas Zverenhoff levou o campeão à presença do próprio Lorde Maxwell, uma honra que a {link:aurora-skycaller}Aurora{/link} não concedia a nenhum estranho havia anos. Tyrosus recebeu o recém-chegado como um aliado digno. Pela primeira vez em muitos anos, o {link:the-bulwark}Baluarte{/link} Argênteo foi aberto a uma mão de fora da ordem.]=],
		},
	},
	mentions = {
		{ text = "Lorde Maxwell Tyrosus" },
		{ text = "{link:the-bulwark}O Baluarte{/link} Argênteo" },
	},
	bonds = {
		{ id = "duke-nicholas-zverenhoff", name = "Duque Nicholas Zverenhoff", note = "traz-lhe campeões" },
		{ id = "leonid-barthalomew", name = "Leonid Barthalomew", note = "um cavaleiro morto-vivo de sua ordem" },
		{ id = "carlin-redpath", name = "Carlin Redpath", note = "um irmão da Aurora" },
	},
})

Translate("ptBR", "duke-nicholas-zverenhoff", {
	title = "Duque Nicholas Zverenhoff",
	subtitle = "Duque da Aurora Argêntea",
	found = "Capela Esperança da Luz, sob as paredes da capela",
	hint = [=[Fale com o duque que concede as comissões da Aurora na Esperança da Luz.]=],
	allegiance = "Aurora Argêntea",
	aliases = { "Zverenhoff", "Nicholas Zverenhoff", "O Duque" },
	sections = {
		{
			title = "Resumo",
			text = [=[O Duque Nicholas Zverenhoff é um dos líderes mais respeitados da {link:argent-dawn}Aurora Argêntea{/link}. É um nobre e um homem culto, conhecido em toda a ordem como um linguista brilhante. Na {link:light-s-hope-chapel}Esperança da Luz{/link}, ele concede a comissão da {link:aurora-skycaller}Aurora{/link} a todos que lutarão por ela e paga por cada pedra do {link:scourge}Flagelo{/link} tomada dos mortos. É cortês com seus aliados e totalmente impiedoso com o Flagelo e com os fanáticos da {link:scarlet-crusade}Cruzada Escarlate{/link}.]=],
		},
		{
			title = "Importância",
			text = [=[O Duque é o recrutador da {link:aurora-skycaller}Aurora{/link} e seu juiz de campeões. Ele acredita que tudo o que é levado ao extremo é um perigo para o mundo, e conta o zelo cego da Cruzada entre esses perigos. Ensina que a Aurora deve ser tolerante e, ainda assim, inflexível em suas crenças. Os que ele julga dignos, leva à presença de {link:lord-maxwell-tyrosus}Lorde Maxwell Tyrosus{/link}.]=],
		},
		{
			title = "Feitos",
			text = [=[• Ele concede a comissão da {link:argent-dawn}Aurora Argêntea{/link}, que permite a seus portadores recolher pedras do {link:scourge}Flagelo{/link} dos caídos.
• Ele troca pedras do Flagelo pelas fichas de bravura da {link:aurora-skycaller}Aurora{/link}.
• Ele estuda escritos estranhos enviados à Aurora, como o livro de um falador de espíritos de {link:winterspring}Hibérnia{/link}.
• Ele envia campeões a Stratholme contra a Cruzada e contra o Flagelo.]=],
		},
		{
			title = "Sem Registro",
			text = [=[Nenhuma crônica registra onde ficavam as terras do Duque antes da praga, nem como ele chegou à {link:aurora-skycaller}Aurora{/link}.]=],
		},
	},
	chapters = {
		{
			title = "A Comissão da Aurora",
			hint = "Aceite a comissão da Aurora na Esperança da Luz.",
			text = [=[Todo soldado que combate o {link:scourge}Flagelo{/link} em nome da {link:aurora-skycaller}Aurora{/link} carrega sua comissão. Com ela, explicou o Duque, o portador pode tomar as pedras do Flagelo que os mortos às vezes carregam, suas marcas de patente. O Duque paga por cada conjunto, e paga melhor que tudo pelas pedras dos suseranos do Flagelo.]=],
		},
		{
			title = "O Arquivista",
			hint = "Ataque os registros da Cruzada Escarlate em Stratholme.",
			text = [=[O Duque perguntou quantos inocentes a Cruzada havia destruído em nome da Luz. Queria seu Arquivista em Stratholme morto e o Arquivo Escarlate queimado. Quando a tarefa foi cumprida, ele se alegrou: anos de conhecimento da Cruzada tinham virado fumaça.]=],
		},
		{
			title = "A Verdade Vem Abaixo",
			hint = [=[Traga ao Duque a prova do que realmente comanda a Cruzada Escarlate.]=],
			text = [=[A cabeça depositada diante do Duque não era de um homem. O Grão-cruzado da {link:scarlet-crusade}Cruzada Escarlate{/link} era um senhor do medo, Balnazzar, irmão do {link:varimathras}Varimathras{/link} que serve na {link:undercity}Cidade Baixa{/link}. Zverenhoff só pôde se perguntar por quanto tempo a Cruzada servira a um demônio sem saber.]=],
		},
		{
			title = "Muito Além do Dever",
			hint = [=[Destrua o senhor de Stratholme e prove ser o campeão do Duque.]=],
			text = [=[Por último, o Duque pediu a cabeça do Barão Rivendare, a quem chamava de moleque de recados de {link:kel-thuzad}Kel'Thuzad{/link}. Quem a trouxe tornou-se seu campeão, o primeiro em muitos anos, e o primeiro estranho em anos a ser levado à presença de {link:lord-maxwell-tyrosus}Lorde Maxwell{/link}.]=],
		},
	},
	mentions = {
		{ text = "Comissão da {link:argent-dawn}Aurora Argêntea{/link}" },
		{ text = "Pedras do {link:scourge}Flagelo{/link} dos Lacaios" },
		{ text = "Pedras do {link:scourge}Flagelo{/link} dos Invasores" },
		{ text = "Pedras do {link:scourge}Flagelo{/link} dos Corruptores" },
		{ text = "Duque Nicholas Zverenhoff" },
		{ text = "O Arquivista" },
		{ text = "A Verdade Vem Abaixo" },
		{ text = "Muito Além do Dever" },
		{ text = "{link:lord-maxwell-tyrosus}Lorde Maxwell Tyrosus{/link}" },
	},
	bonds = {
		{ id = "lord-maxwell-tyrosus", name = "Lorde Maxwell Tyrosus", note = "o líder a quem serve" },
		{ id = "betina-bigglezink", name = "Betina Bigglezink", note = "trabalha a seu lado" },
		{ id = "carlin-redpath", name = "Carlin Redpath", note = "trabalha a seu lado" },
	},
})

Translate("ptBR", "carlin-redpath", {
	title = "Carlin Redpath",
	subtitle = "Sobrevivente da Vila das Flechas",
	found = "Capela Esperança da Luz",
	hint = [=[Procure o homem enlutado da Vila das Flechas que serve à Aurora na Esperança da Luz.]=],
	allegiance = "Aurora Argêntea",
	aliases = { "Carlin", "Irmão Carlin", "Tio Carlin" },
	sections = {
		{
			title = "Resumo",
			text = [=[Carlin Redpath é um soldado da {link:argent-dawn}Aurora Argêntea{/link} na {link:light-s-hope-chapel}Capela Esperança da Luz{/link}. Nasceu na {link:darrowshire}Vila das Flechas{/link} e é um dos pouquíssimos que sobreviveram à batalha que a destruiu. Seu irmão era o {link:joseph-redpath}Capitão Joseph Redpath{/link}, que liderou a defesa da aldeia. Sua sobrinha pequena, {link:pamela-redpath}Pamela{/link}, está morta. Carlin transformou seu luto num único propósito: vingança contra o {link:scourge}Flagelo{/link} que lhe tomou o lar.]=],
		},
		{
			title = "Importância",
			text = [=[Carlin é a memória viva da {link:darrowshire}Vila das Flechas{/link}. Seus heróis, seus vilões e seus mortos clamam por ele em sonhos. Quando os Anais da Vila das Flechas lhe foram trazidos, ele soube que talvez ainda pudesse fazer por eles mais do que chorar.]=],
		},
		{
			title = "Feitos",
			text = [=[• Ele sobreviveu à batalha da {link:darrowshire}Vila das Flechas{/link} e à traição do irmão.
• Ele serve à {link:argent-dawn}Aurora Argêntea{/link} na {link:light-s-hope-chapel}Esperança da Luz{/link}.
• Ele reuniu as relíquias da batalha da Vila das Flechas para que o destino da aldeia pudesse ser mudado.]=],
		},
	},
	chapters = {
		{
			title = "Tio Carlin",
			hint = [=[Leve a Carlin notícias da menininha que ainda espera na Vila das Flechas.]=],
			text = [=[Carlin acreditava que {link:pamela-redpath}Pamela{/link} talvez estivesse viva. Quando soube que ela estava morta e ainda esperava como fantasma, exclamou que trocaria de lugar com ela num instante. Depois pôs o luto de lado e pediu que os espíritos atormentados dos defensores da {link:darrowshire}Vila das Flechas{/link} fossem libertados do {link:scourge}Flagelo{/link}, pois muitos deles agora o servem como carniçais e esfoladores.]=],
		},
		{
			title = "Os Anais da Vila das Flechas",
			hint = [=[Leve os Anais Estendidos da Vila das Flechas à Esperança da Luz.]=],
			text = [=[Uma gnoma estranha em {link:ruins-of-andorhal}Andorhal{/link} havia lançado sua magia sobre os Anais da {link:darrowshire}Vila das Flechas{/link}, e novas páginas haviam surgido no fim do livro. Elas falavam dos dias após a batalha, e uma delas falava do próprio Carlin. Ele as leu e não soube dizer se eram verdadeiras. Decidiu descobrir.]=],
		},
		{
			title = "Heróis e Vilões",
			hint = [=[Reúna as relíquias dos heróis e dos vilões da Vila das Flechas.]=],
			text = [=[Os Anais nomeavam todos. O incunábulo do paladino {link:davil-lightfire}Davil Lightfire{/link} fora levado para {link:hearthglen}Amparo{/link}. O escudo rachado do {link:joseph-redpath}Capitão Redpath{/link} jazia perto de um celeiro no oeste. O crânio do senhor carniçal {link:horgus-the-ravager}Horgus{/link} jazia num lago, e a espada quebrada de Marduk, o Negro, numa garganta perto do {link:corin-s-crossing}Cruzamento de Corin{/link}. Por último vinham os crânios dos campeões do {link:scourge}Flagelo{/link} que haviam lutado na batalha. Carlin não entendia bem por que essas relíquias importavam. Apenas sentia que estavam ligadas ao seu lar.]=],
		},
		{
			title = "De Volta a Chromie",
			hint = "Envie as relíquias da Vila das Flechas à gnoma em Andorhal.",
			text = [=[Quando todas as relíquias foram reunidas, Carlin as enviou para o oeste, à gnoma {link:chromie}Chromie{/link}, na estalagem arruinada de {link:ruins-of-andorhal}Andorhal{/link}. Ela lhe dissera algo em que ele mal ousava acreditar: que a {link:darrowshire}Vila das Flechas{/link} podia ser salva.]=],
		},
	},
	mentions = {
		{ text = "Tio Carlin" },
		{ text = "Defensores da {link:darrowshire}Vila das Flechas{/link}" },
		{ text = "Irmão Carlin" },
		{ text = "Heróis da {link:darrowshire}Vila das Flechas{/link}" },
		{ text = "Vilões da {link:darrowshire}Vila das Flechas{/link}" },
		{ text = "Saqueadores da {link:darrowshire}Vila das Flechas{/link}" },
		{ text = "De Volta a {link:chromie}Chromie{/link}" },
	},
	bonds = {
		{ id = "joseph-redpath", name = "Joseph Redpath", note = "seu irmão" },
		{ id = "pamela-redpath", name = "Pamela Redpath", note = "sua sobrinha" },
		{ id = "marshal-redpath", name = "Marechal Redpath", note = "compartilha seu nome; nenhum parentesco está registrado" },
		{ id = "lord-maxwell-tyrosus", name = "Lorde Maxwell Tyrosus", note = "lidera sua ordem" },
	},
})

Translate("ptBR", "pamela-redpath", {
	title = "Pamela Redpath",
	subtitle = "A Criança da Vila das Flechas",
	found = "A casa de sua família, ao sul das ruínas da Vila das Flechas",
	hint = [=[Procure a menininha que espera numa casa ao sul da Vila das Flechas.]=],
	allegiance = "Vila das Flechas",
	aliases = { "Pamela", "Pequena Pamela" },
	sections = {
		{
			title = "Resumo",
			text = [=[Pamela Redpath é o fantasma de uma menininha da {link:darrowshire}Vila das Flechas{/link}. Quando o {link:scourge}Flagelo{/link} chegou, seu pai, o {link:joseph-redpath}Capitão Joseph Redpath{/link}, foi lutar, e sua tia {link:marlene-redpath}Marlene{/link} lhe disse que ficasse em casa e se escondesse. Ela espera ali desde então. Não sabe que está morta. Não sabe o que aconteceu com o pai. Sabe apenas que ele não veio buscá-la, que vozes más às vezes sussurram para ela no escuro e que deixou sua boneca na cidade.]=],
		},
		{
			title = "Importância",
			text = [=[Pamela é o mais triste dos fantasmas das Terras Pestilentas, e o que mais comoveu corações. Sua tia, seu tio e sua irmã pediram, cada um, a estranhos que a encontrassem. Por meio dela, a história da {link:darrowshire}Vila das Flechas{/link} e dos {link:joseph-redpath}Redpath{/link} volta à luz.]=],
		},
		{
			title = "Sua Família",
			text = [=[Seu pai era o {link:joseph-redpath}Capitão Joseph Redpath{/link}, que liderou a defesa da {link:darrowshire}Vila das Flechas{/link}. Sua tia {link:marlene-redpath}Marlene{/link} a escondeu quando a batalha começou e agora vaga como espírito perto de {link:ruins-of-andorhal}Andorhal{/link}. Seu tio {link:carlin-redpath}Carlin{/link} serve à {link:argent-dawn}Aurora Argêntea{/link} na {link:light-s-hope-chapel}Esperança da Luz{/link}. Sua irmã mais velha, {link:jessica-redpath}Jessica{/link}, fugiu de {link:lordaeron}Lordaeron{/link} antes da praga e vive longe, em {link:winterspring}Hibérnia{/link}. Pamela se lembra de que Jessica chorou ao partir, e não entende por quê.]=],
		},
	},
	chapters = {
		{
			title = "Pequena Pamela",
			hint = "Encontre a criança que seus parentes procuram.",
			text = [=[Pamela cumprimentou seu visitante e perguntou seu nome. Falou do pai, o homem mais corajoso do mundo inteiro, e da irmã {link:jessica-redpath}Jessica{/link}, que se escondia com ela e saltava para surpreender o pai quando ele chegava em casa.]=],
		},
		{
			title = "A Boneca de Pamela",
			hint = "Encontre a boneca que Pamela deixou na cidade.",
			text = [=[A boneca estava em algum lugar nas ruínas da {link:darrowshire}Vila das Flechas{/link}, onde os mortos ainda andam. Quando foi encontrada e trazida de volta, Pamela ficou radiante. Foi a primeira coisa a confortá-la em muito, muito tempo.]=],
		},
		{
			title = "A Batalha da Vila das Flechas",
			hint = [=[Tome parte na batalha da Vila das Flechas e traga um pai para casa.]=],
			text = [=[Com o feitiço da gnoma {link:chromie}Chromie{/link}, a batalha da {link:darrowshire}Vila das Flechas{/link} foi travada de novo entre seus fantasmas. Dessa vez, o {link:joseph-redpath}Capitão Redpath{/link} foi salvo. Quando a luta terminou, Pamela ouviu o pai sussurrar para ela. Ele disse que havia espantado os fantasmas e que estava voltando para casa. Ela fez chá, com muito açúcar, para quem o ajudara. Depois deu a esse amigo uma chave do pai, que abria um baú escondido atrás da casa.]=],
		},
	},
	mentions = {
		{ text = "Irmã Pamela" },
		{ text = "Pequena Pamela" },
		{ text = "A Boneca de Pamela" },
		{ text = "Tia {link:marlene-redpath}Marlene{/link}" },
		{ text = "{link:carlin-redpath}Tio Carlin{/link}" },
		{ text = "A Batalha da {link:darrowshire}Vila das Flechas{/link}" },
		{ text = "Tesouros Escondidos" },
	},
	bonds = {
		{ id = "joseph-redpath", name = "Joseph Redpath", note = "seu pai" },
		{ id = "carlin-redpath", name = "Carlin Redpath", note = "seu tio" },
		{ id = "marlene-redpath", name = "Marlene Redpath", note = "sua tia, que a escondeu" },
		{ id = "jessica-redpath", name = "Jessica Redpath", note = "sua irmã mais velha" },
	},
})

