			text = [=[Demetria é a principal conselheira do Grão-cruzado da {link:scarlet-crusade}Cruzada Escarlate{/link}. É chamada de Oráculo por causa dos sentidos que, diz-se, possui além dos de outros mortais. Seus conselhos deram à Cruzada várias vitórias contra o {link:scourge}Flagelo{/link}. Quando os {link:forsaken}Renegados{/link} reescreveram as ordens da Cruzada, ela foi enviada de {link:tyr-s-hand}Manopla de Tyr{/link} para o norte, rumo a Stratholme, com seus guardas, e {link:nathanos-blightcaller}Nathanos Blightcaller{/link} mandou seus caçadores ao seu encontro na estrada.]=],
		},
	},
	mentions = {
		{ text = "O Mensageiro Carmesim" },
		{ text = "O Oráculo Escarlate, Demetria" },
	},
	bonds = {
		{ id = "nathanos-blightcaller", name = "Nathanos Blightcaller", note = "mandou caçadores atrás dela" },
		{ id = "crusader-lord-valdelmar", name = "Lorde Cruzado Valdelmar", note = "enviou-a ao norte" },
	},
})

