	aliases = { "Aurora" },
	sections = {
		{
			title = "Resumo",
			text = [=[Aurora Skycaller é uma alta elfa que vive perto da {link:northpass-tower}Torre do Passo Norte{/link}. Ela não gosta de falar da história de seu povo, pois dói-lhe que os erros de seus ancestrais jamais possam ser desfeitos. Ainda assim, quando um {link:dwarves}anão{/link} da {link:explorers-league}Liga dos Exploradores{/link} lhe enviou os fragmentos de uma relíquia despedaçada do {link:lake-kel-theril}Lago Kel'Theril{/link}, em {link:winterspring}Hibérnia{/link}, ela a reconheceu como o {link:crystal-of-zin-malor}Cristal de Zin-Malor{/link}, capaz de conter e comandar grandes forças arcanas. Com os escritos sagrados dos Bem-nascidos e os reagentes certos, ela o refez inteiro, para que pudesse ser mostrado aos espíritos amaldiçoados que o haviam roubado muito tempo atrás.]=],
		},
	},
	mentions = {
		{
			text = [=[Espíritos Atormentados de {link:lake-kel-theril}Kel'Theril{/link}]=],
		},
		{ text = "Fragmentos do Passado" },
		{ text = "Fragmentos do Passado" },
		{ text = "Atormentados pelo Passado" },
	},
})

