Translate("ptBR", "infiltrator-hameya", {
	title = "Infiltrador Hameya",
	subtitle = "O Mossflayer Infectado",
	found = "Perto de Zul'Mashar",
	hint = [=[Encontre o troll que implorou pela morte antes que a praga lhe tomasse a vontade.]=],
	allegiance = "Flagelo",
	aliases = { "Hameya" },
	sections = {
		{
			title = "Resumo",
			text = [=[Hameya era um troll Mossflayer. Na estrada para {link:zul-mashar}Zul'Mashar{/link}, ele e seus companheiros comeram carne estragada, e ela os transformou. Hameya sentia as palavras de um lich em sua mente, instigando-o a voltar para casa e infectar seu povo. Antes que sua vontade o abandonasse, escreveu um pergaminho que implorava a quem o encontrasse que o matasse. Ele enterrara um baú ao lado de uma carroça atrás da {link:the-undercroft}Chácara Secreta{/link} e guardava a única chave. Agora o {link:scourge}Flagelo{/link} o chama de infiltrador, e ele caminha em direção ao seu próprio povo.]=],
		},
	},
	mentions = {
		{ text = "A Súplica de Hameya" },
	},
})

